package com.jadhavr.erp.attendance.util;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Small dependency-free PDF writer for plain attendance summaries. */
public final class SimplePdfExporter {private SimplePdfExporter(){}
 public static byte[] create(List<String> lines){try{ByteArrayOutputStream out=new ByteArrayOutputStream();List<Integer> offsets=new ArrayList<>();write(out,"%PDF-1.4\n");String text="BT /F1 12 Tf 50 790 Td "+lines.stream().map(SimplePdfExporter::escape).map(s->"("+s+") Tj 0 -20 Td").reduce("",(a,b)->a+b+" ")+"ET";String[] objects={"<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>","<< /Length "+text.getBytes(StandardCharsets.ISO_8859_1).length+" >>\nstream\n"+text+"\nendstream","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"};for(int i=0;i<objects.length;i++){offsets.add(out.size());write(out,(i+1)+" 0 obj\n"+objects[i]+"\nendobj\n");}int xref=out.size();write(out,"xref\n0 6\n0000000000 65535 f \n");for(int o:offsets)write(out,String.format("%010d 00000 n \n",o));write(out,"trailer << /Size 6 /Root 1 0 R >>\nstartxref\n"+xref+"\n%%EOF");return out.toByteArray();}catch(IOException e){throw new IllegalStateException("Could not create PDF",e);}}
 private static String escape(String s){return s.replace("\\","\\\\").replace("(","\\(").replace(")","\\)");}private static void write(OutputStream out,String s)throws IOException{out.write(s.getBytes(StandardCharsets.ISO_8859_1));}
}
